/// Returns a new vector where each element is `arr1[i] - arr2[i]`.
/// Assumes `arr1.len() == arr2.len()` and that all differences fit in `i32`.
fn element_wise_subtract(arr1: &Vec<i32>, arr2: &Vec<i32>) -> Vec<i32> {
    // If lengths might ever differ in real usage, this makes the assumption explicit.
    debug_assert_eq!(arr1.len(), arr2.len());

    arr1.iter()
        .zip(arr2.iter())
        .map(|(&a, &b)| a - b)
        .collect()
}

fn main() {
    let a = vec![10, -3, 7];
    let b = vec![4,  5, -2];

    let result = element_wise_subtract(&a, &b);
    println!("{result:?}"); // [6, -8, 9]
}